// Turns each new job into one sheet row. Nothing new means nothing is written.
const jobs = $input.all().map((i) => i.json).filter((j) => j.jobId && j.title);
const today = new Date().toISOString().slice(0, 10);
const salary = (j) => {
  if (!j.salaryMin && !j.salaryMax) return '';
  const f = (n) => (n ? Number(n).toLocaleString('en-US') : '?');
  return `${f(j.salaryMin)} - ${f(j.salaryMax)} ${j.salaryCurrency || ''}`.trim();
};
return jobs.map((j) => ({ json: {
  'Found on': today,
  Company: j.company,
  Title: j.title,
  Department: j.department || '',
  Location: j.location || '',
  Remote: j.remote === true ? 'yes' : j.remote === false ? 'no' : '',
  Salary: salary(j),
  Posted: j.postedAt ? String(j.postedAt).slice(0, 10) : '',
  Link: j.url,
  Board: j.ats,
}}));
